[CmdletBinding()]
param(
    [string]$ComfyUrl = 'http://127.0.0.1:8188',
    [string]$WorkflowPath = 'C:\install\AI\Workflows\13_sd15_ipadapter_face_v1_api.json',
    [string]$ComfyInput = 'C:\install\AI\ComfyUI\input',
    [string]$MasterPath = 'C:\install\AI\Data\Characters\15\standard\identity_front.png',
    [string]$OutputRoot = 'C:\install\AI\Data\QA\identity_pipeline_20260816\targeted_views_probe',
    [int]$TimeoutSeconds = 900
)

$ErrorActionPreference = 'Stop'
New-Item -ItemType Directory -Force -Path $ComfyInput, $OutputRoot | Out-Null
$masterName='identity_targeted_master_20260816.png';if(-not(Test-Path -LiteralPath (Join-Path $ComfyInput $masterName))){Copy-Item -LiteralPath $MasterPath -Destination (Join-Path $ComfyInput $masterName)}
$base=Get-Content -LiteralPath $WorkflowPath -Raw -Encoding UTF8|ConvertFrom-Json
function Clone($x){$x|ConvertTo-Json -Depth 100 -Compress|ConvertFrom-Json}
function Submit($wf,[string]$id,[string]$view,[int64]$seed,[string]$prompt,[string]$path){$t=Get-Date;try{$body=@{prompt=$wf;client_id="identity-targeted-20260816-$id-$seed"}|ConvertTo-Json -Depth 100 -Compress;$r=Invoke-RestMethod "$ComfyUrl/prompt" -Method Post -Body ([Text.Encoding]::UTF8.GetBytes($body)) -ContentType 'application/json';$promptId=[string]$r.prompt_id;$end=(Get-Date).AddSeconds($TimeoutSeconds);$e=$null;do{Start-Sleep 2;try{$h=Invoke-RestMethod "$ComfyUrl/history/$promptId";$p=$h.PSObject.Properties[$promptId];if($p){$e=$p.Value}}catch{}}while($null -eq $e -and (Get-Date)-lt $end);if($null -eq $e){throw "Timed out $promptId"};if($e.status.status_str -eq 'error'){throw($e.status|ConvertTo-Json -Depth 30 -Compress)};$items=@();foreach($n in $e.outputs.PSObject.Properties){$c=$n.Value.PSObject.Properties['images'];if($c){$items+=@($c.Value)}};if($items.Count -eq 0){throw 'No image output'};$i=$items[0];$q="filename=$([Uri]::EscapeDataString([string]$i.filename))&subfolder=$([Uri]::EscapeDataString([string]$i.subfolder))&type=$([Uri]::EscapeDataString([string]$i.type))";Invoke-WebRequest "$ComfyUrl/view?$q" -OutFile $path -UseBasicParsing;return [ordered]@{candidateId=$id;requestedView=$view;seed=$seed;status='Succeeded';path=$path;promptId=$promptId;prompt=$prompt;durationMs=[int]((Get-Date)-$t).TotalMilliseconds;error=$null}}catch{return [ordered]@{candidateId=$id;requestedView=$view;seed=$seed;status='Failed';path=$null;promptId=$null;prompt=$prompt;durationMs=[int]((Get-Date)-$t).TotalMilliseconds;error=$_.Exception.Message}}}
$cases=@(
    [pscustomobject]@{id='TV01';view='Left45';width=640;height=832;prompt='same adult East Asian man as the reference, preserve exact face, short black hair, trimmed mustache and goatee, dark navy collared shirt, true left 45 degree three-quarter view, head and upper body, both eyes visible, no prop, photorealistic live-action'},
    [pscustomobject]@{id='TV02';view='Right45';width=640;height=832;prompt='same adult East Asian man as the reference, preserve exact face, short black hair, trimmed mustache and goatee, dark navy collared shirt, true right 45 degree three-quarter view, head and upper body, both eyes visible, no prop, photorealistic live-action'},
    [pscustomobject]@{id='TV03';view='HalfBody';width=576;height=896;prompt='same adult East Asian man as the reference, preserve exact face, short black hair, trimmed mustache and goatee, dark navy collared shirt, medium half-body portrait to the waist, hands away from face, no prop, photorealistic live-action'},
    [pscustomobject]@{id='TV04';view='FullBody';width=576;height=1024;prompt='same adult East Asian man as the reference, preserve exact face, short black hair, trimmed mustache and goatee, dark navy collared shirt, full-body standing portrait, head to shoes visible, natural proportions, no prop, photorealistic live-action'}
)
$results=[System.Collections.Generic.List[object]]::new();foreach($c in $cases){$wf=Clone $base;$wf.'4'.inputs.image=$masterName;$wf.'2'.inputs.text=$c.prompt;$wf.'3'.inputs.text='different person, identity drift, changing face, changed hairstyle, changed clothing, multiple people, duplicate face, extra limbs, malformed hands, cropped head, cropped feet, prop, text, watermark, cartoon, CGI';$wf.'6'.class_type='EmptyLatentImage';$wf.'6'.inputs=@{width=$c.width;height=$c.height;batch_size=1};$wf.'7'.inputs.denoise=1.0;$wf.'7'.inputs.steps=28;$wf.'7'.inputs.seed=[int64](1700000+($results.Count+1));$wf.'9'.inputs.filename_prefix="video_studio/identity_targeted_20260816_$($c.view)";$target=Join-Path $OutputRoot "$($c.id)_$($c.view).png";$row=Submit $wf $c.id $c.view ([int64]$wf.'7'.inputs.seed) $c.prompt $target;$results.Add($row);Write-Output("{0} {1} {2} {3}ms" -f $c.id,$c.view,$row.status,$row.durationMs)}
$manifest=[ordered]@{schemaVersion='2026-08-16.identity-targeted-probe.v1';masterPath=$MasterPath;identityThreshold=.85;candidates=@($results|Where-Object status -eq 'Succeeded'|ForEach-Object{[ordered]@{path=$_.path;candidateId=$_.candidateId;requestedView=$_.requestedView;sourcePrompt=$_.prompt;seed=$_.seed}});generationResults=@($results)};$manifest|ConvertTo-Json -Depth 40|Set-Content -LiteralPath (Join-Path $OutputRoot 'targeted-view-manifest.json') -Encoding UTF8
